import functools
import inspect
from typing import ForwardRef
from fastapi.dependencies.utils import get_typed_signature, get_typed_return_annotation

# We need the original function to be defined in a scope where the forward ref can be resolved
# and the wrapper to be defined in a scope where it cannot.

def create_original():
    def original_func(a: "MyClass"):
        return a
    return original_func

class MyClass:
    pass

original_func = create_original()

def wrapper(func):
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapped

wrapped_func = wrapper(original_func)

print("Testing get_typed_signature with wrapped function...")
try:
    sig = get_typed_signature(wrapped_func)
    print("Success!")
    for param in sig.parameters.values():
        print(f"Param {param.name}: {param.annotation}")
except Exception as e:
    print(f"Failed: {e}")
    import traceback
    traceback.print_exc()

